'use client';

import Link from 'next/link';
import type { FooterProps } from './Footer.types';
import { layoutConfig, servicesRegistry } from '@/data';

export function Footer({ onContactOpen, onNavigate }: FooterProps = {}) {
  const { footer } = layoutConfig;

  const handleContact = () => {
    if (onContactOpen) {
      onContactOpen();
    } else if (typeof window !== 'undefined') {
      window.dispatchEvent(new CustomEvent('open-contact'));
    }
  };

  const handleLinkClick = (e: React.MouseEvent<HTMLAnchorElement>, href: string) => {
    if (onNavigate) {
      e.preventDefault();
      onNavigate(href);
    }
  };

  // Build columns dynamically so the Services column pulls straight from servicesRegistry
  const footerColumns = [
    footer.columns[0], // Pages
    {
      title: 'Services',
      links: [
        { label: 'All Services', href: '/services' },
        ...servicesRegistry.map((s) => ({
          label: s.navLabel,
          href: `/services/${s.slug}`,
        })),
      ],
    },
    footer.columns[2], // Connect
  ];

  return (
    <div className="w-full">
      {/* ── Section: Tech Marquee & Call To Action Banner ── */}
      <section className="w-full pt-4 pb-4">
        {/* Tech Stacks & Skills Scrolling Marquee */}
        <div className="px-4 sm:px-6 lg:px-10 w-full mt-2 sm:mt-4 mb-10 sm:mb-16 lg:mb-20 select-none">
          <div
            className="w-full overflow-hidden py-2"
            style={{
              maskImage:
                'linear-gradient(to right, transparent 0%, black 8%, black 92%, transparent 100%)',
              WebkitMaskImage:
                'linear-gradient(to right, transparent 0%, black 8%, black 92%, transparent 100%)',
            }}
          >
            <div className="flex w-max whitespace-nowrap animate-[marquee_34s_linear_infinite] will-change-transform">
              {[...footer.techStacks, ...footer.techStacks].map((skill, index) => (
                <div
                  key={`${skill}-${index}`}
                  className="flex items-center gap-6 sm:gap-10 mx-3 sm:mx-5 shrink-0"
                >
                  <span className="font-['Gt_Pressura_Mono',Georgia,monospace] text-[11px] sm:text-[13px] uppercase tracking-[0.18em] text-[var(--text)] opacity-60 font-normal">
                    {skill}
                  </span>
                  <span className="text-[8px] text-[var(--text)] opacity-30 select-none">✦</span>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Ready for your next product CTA Banner */}
        <div className="px-4 sm:px-6 lg:px-10 my-2 sm:my-3 lg:my-4 w-full">
          <div
            data-cursor-invert="true"
            className="w-full h-[calc(100vh-2.5rem)] sm:h-[calc(100vh-3.5rem)] lg:h-[calc(100vh-4.5rem)] min-h-[560px] max-h-[860px] rounded-[4px] bg-[#111111] dark:bg-[#161618] border border-black/10 dark:border-white/10 px-6 sm:px-10 flex flex-col items-center justify-center text-center overflow-hidden relative"
          >
            {/* Subtitle */}
            <span className="font-['PP_Neue_Montreal_Medium',sans-serif] text-[14px] text-neutral-400 font-normal tracking-normal mb-4 sm:mb-6 select-none">
              {footer.banner.subtitle}
            </span>

            {/* Large Display Heading */}
            <h2 className="font-['PP_Neue_Corp_Tight_Ultrabold'] text-[clamp(3.5rem,9.5vw,10.5rem)] text-[#ebe9e4] uppercase leading-[0.85] tracking-[-0.01em] select-none max-w-6xl">
              {footer.banner.headingLine1}
              <br />
              {footer.banner.headingLine2}
            </h2>

            {/* Book a Call Button */}
            <button
              onClick={handleContact}
              data-cursor-hover={footer.banner.buttonText}
              data-cursor-icon="↗"
              aria-label={footer.banner.buttonText}
              className="mt-8 sm:mt-12 relative overflow-hidden inline-flex items-center gap-2.5 sm:gap-3 px-3.5 py-2 sm:px-4 sm:py-2 rounded-[4px] bg-[#ebe9e4] text-black transition-all duration-300 hover:scale-[1.03] active:scale-[0.98] group cursor-pointer"
            >
              {/* Blue background fill scaling from left to right on hover */}
              <span
                aria-hidden="true"
                className="absolute inset-0 bg-blue-600 origin-left scale-x-0 group-hover:scale-x-100 transition-transform duration-500 ease-out pointer-events-none"
              />
              <img
                src={footer.banner.avatar.src}
                alt={footer.banner.avatar.alt}
                className="relative z-10 w-5 h-5 sm:w-6 sm:h-6 rounded-[3px] object-cover shrink-0"
              />
              <span className="relative z-10 font-['PP_Neue_Montreal_Medium',sans-serif] text-[13px] sm:text-[14px] font-medium tracking-normal text-black transition-colors duration-300 group-hover:text-white">
                {footer.banner.buttonText}
              </span>
            </button>
          </div>
        </div>
      </section>

      {/* ── The Footer ── */}
      <footer id="footer" className="footer w-full relative overflow-hidden">
        <div className="meta px-4 sm:px-6 lg:px-10 pt-8 sm:pt-12 pb-6 w-full">
          {/* 3 Columns Grid */}
          <div className="grid grid-cols-1 md:grid-cols-12 gap-6 sm:gap-8 lg:gap-12 w-full">
            {/* Column 1 (Left - Cols 1-6): Icon & Badge */}
            <div className="col-span-1 md:col-span-6 border-t border-black/15 dark:border-white/15 pt-5 sm:pt-6 flex flex-col justify-start items-start">
              <img
                src={footer.brandBadge.icon.src}
                alt={footer.brandBadge.icon.alt}
                className="w-8 h-8 sm:w-10 sm:h-10 mb-4 object-contain"
              />
              <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-black dark:bg-white/10 text-white dark:text-neutral-200 text-[12px] font-['PP_Neue_Montreal_Medium',sans-serif] tracking-normal select-none">
                <span className="text-[12px]">{footer.brandBadge.symbol}</span>
                <span>{footer.brandBadge.text}</span>
              </div>
            </div>

            {/* Column 2 & 3: Navigation & Links */}
            <nav aria-label="Footer navigation" className="contents">
              {/* Column 2 (Middle - Cols 7-9): Dynamic Pages & Services */}
              <div className="col-span-1 md:col-span-3 border-t border-black/15 dark:border-white/15 pt-5 sm:pt-6 flex flex-col items-start gap-2">
                <span className="font-['PP_Neue_Montreal_Medium',sans-serif] text-[11px] uppercase tracking-wider text-[#888] mb-1">
                  {footerColumns[0].title}
                </span>
                {footerColumns[0].links.map((link) => (
                  <Link
                    key={link.label}
                    href={link.href}
                    className="font-['PP_Neue_Montreal_Medium',sans-serif] text-[14px] leading-[1.2] text-[#555] dark:text-[#aaa] hover:text-[#111] dark:hover:text-white transition-colors duration-150"
                  >
                    {link.label}
                  </Link>
                ))}
                <button
                  onClick={handleContact}
                  className="font-['PP_Neue_Montreal_Medium',sans-serif] text-[14px] leading-[1.2] text-[#555] dark:text-[#aaa] hover:text-[#111] dark:hover:text-white transition-colors duration-150 text-left cursor-pointer"
                >
                  Contact
                </button>
              </div>

              {/* Column 3 (Right - Cols 10-12): Services & Social */}
              <div className="col-span-1 md:col-span-3 border-t border-black/15 dark:border-white/15 pt-5 sm:pt-6 flex flex-col items-start gap-2">
                <span className="font-['PP_Neue_Montreal_Medium',sans-serif] text-[11px] uppercase tracking-wider text-[#888] mb-1">
                  {footerColumns[1].title}
                </span>
                {footerColumns[1].links.map((link) => (
                  <Link
                    key={link.label}
                    href={link.href}
                    className="font-['PP_Neue_Montreal_Medium',sans-serif] text-[14px] leading-[1.2] text-[#555] dark:text-[#aaa] hover:text-[#111] dark:hover:text-white transition-colors duration-150"
                  >
                    {link.label}
                  </Link>
                ))}

                <span className="font-['PP_Neue_Montreal_Medium',sans-serif] text-[11px] uppercase tracking-wider text-[#888] mt-3 mb-1">
                  {footerColumns[2].title}
                </span>
                {footerColumns[2].links.map((link) => (
                  <a
                    key={link.label}
                    href={link.href}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="font-['PP_Neue_Montreal_Medium',sans-serif] text-[14px] leading-[1.2] text-[#555] dark:text-[#aaa] hover:text-[#111] dark:hover:text-white transition-colors duration-150"
                  >
                    {link.label}
                  </a>
                ))}
              </div>
            </nav>
          </div>

          {/* Bottom Row */}
          <div className="grid grid-cols-1 md:grid-cols-12 gap-6 sm:gap-8 lg:gap-12 items-center mt-6 sm:mt-8 pt-3 sm:pt-4 border-t border-black/15 dark:border-white/15 text-[14px] leading-[1.2] font-['PP_Neue_Montreal_Medium',sans-serif] text-[#555] dark:text-[#aaa]">
            <div className="col-span-1 md:col-span-6 text-left">
              {footer.bottomRow.copyright}
            </div>
            <div className="col-span-1 md:col-span-3 text-left">
              {footer.bottomRow.legalNotice}
            </div>
            <div className="col-span-1 md:col-span-3 text-left">
              {footer.bottomRow.location}
            </div>
          </div>
        </div>
      </footer>
    </div>
  );
}
